package org.rhetos.arn

import kotlinx.browser.document
import org.w3c.dom.HTMLAnchorElement

class NotFound {
    fun main() {
        val title = document.createElement("h1")
        title.textContent = "Erreur 404 (page introuvable)"

        val image = document.createElement("img")
        image.className = "image"
        image.setAttribute("src", "/pictures/404_picture.webp")
        image.setAttribute("alt", "Perdu ?")

        val description = document.createElement("h2")
        description.textContent = "Il semblerait que vous soyez perdu..."

        val returnButton = document.createElement("a") as HTMLAnchorElement
        returnButton.textContent = "Retour à l'accueil"
        returnButton.href = "/Rhetos2627-web/"

        app.appendChild(title)
        app.appendChild(image)
        app.appendChild(description)
        app.appendChild(returnButton)
    }
}