package org.rhetos.arn

import kotlinx.browser.document
import kotlinx.browser.window
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.await
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json
import org.rhetos.arn.json.News
import org.w3c.dom.HTMLAnchorElement

class NewsPage {

    private val scope = MainScope()

    fun main() {
        scope.launch {
            val response = window.fetch("jsonData/news.json").await()
            val json = response.text().await()
            val news = Json.decodeFromString<List<News>>(json)

            val container = document.getElementById("news")!!

            val menuTitle = document.createElement("h1")
            menuTitle.textContent = "Actualités"

            container.appendChild(menuTitle)

            for (article in news) {
                val element = document.createElement("a") as HTMLAnchorElement

                element.className = "element"
                element.href = "html/article?id=${article.id}"

                val title = document.createElement("h2")
                title.textContent = "(" + article.date + "): " + article.title

                val description = document.createElement("p")
                description.textContent = article.short

                element.appendChild(title)
                element.appendChild(description)

                container.appendChild(element)
            }
        }
    }
}